package dev.gbppimentel.zzz;
import android.app.*;import android.content.*;import org.json.*;
public class ReminderReceiver extends BroadcastReceiver {
 static PendingIntent pending(Context c,String key,String title,String text){return PendingIntent.getBroadcast(c,key.hashCode(),new Intent(c,ReminderReceiver.class).setAction(key).putExtra("title",title).putExtra("text",text),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c,String key,String title,String text,long at){if(at<System.currentTimeMillis()+10000)return;((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending(c,key,title,text));try{android.content.SharedPreferences p=c.getSharedPreferences("reminders",0);p.edit().putString(key,new JSONObject().put("title",title).put("text",text).put("at",at).toString()).apply();}catch(Exception ignored){}}
 static void cancel(Context c,String key){((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(pending(c,key,"",""));c.getSharedPreferences("reminders",0).edit().remove(key).apply();}
 static void cancelAll(Context c){for(String key:c.getSharedPreferences("reminders",0).getAll().keySet())cancel(c,key);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancelAll();}
 @Override public void onReceive(Context c,Intent i){if(!c.getSharedPreferences("eridu",0).getBoolean("reminders",false))return;NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("eridu","New Eridu reminders",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);n.notify(i.getAction().hashCode(),new Notification.Builder(c,"eridu").setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle(i.getStringExtra("title")).setContentText(i.getStringExtra("text")).setContentIntent(open).setAutoCancel(true).build());c.getSharedPreferences("reminders",0).edit().remove(i.getAction()).apply();}
}
